import pandas as pd
import numpy as np


def _normalize_sku(s):
    if pd.isna(s):
        return None
    return str(s).strip().upper()


def run(inputs: dict) -> dict:
    orders = inputs["orders"].copy()
    price_list = inputs["price_list"].copy()

    # --- src -> exp: derive sku_norm ---
    orders["sku_norm"] = orders["sku"].apply(_normalize_sku)

    # prepare price_list with normalized sku for matching
    price_list = price_list.copy()
    price_list["sku_norm"] = price_list["sku"].apply(_normalize_sku)

    # --- lkp: effective-dated lookup with tie-break ---
    def do_lookup(row):
        sku_norm = row["sku_norm"]
        order_date = row["order_date"]

        if sku_norm is None or pd.isna(sku_norm):
            return pd.Series({"unit_price": 0.0, "price_flag": "NO_PRICE"})

        if pd.isna(order_date):
            candidates = price_list[
                (price_list["sku_norm"] == sku_norm)
                & price_list["valid_from"].notna()
                & False  # order_date NaT -> no valid_from <= NaT comparison holds
            ]
        else:
            candidates = price_list[
                (price_list["sku_norm"] == sku_norm)
                & (price_list["valid_from"] <= order_date)
            ]

        if candidates.empty:
            return pd.Series({"unit_price": 0.0, "price_flag": "NO_PRICE"})

        max_date = candidates["valid_from"].max()
        candidates2 = candidates[candidates["valid_from"] == max_date]
        min_list_id = candidates2["list_id"].min()
        best_rows = candidates2[candidates2["list_id"] == min_list_id]
        best = best_rows.iloc[0]

        return pd.Series({"unit_price": float(best["unit_price"]), "price_flag": "OK"})

    lookup_results = orders.apply(do_lookup, axis=1)
    orders = pd.concat([orders, lookup_results], axis=1)

    # --- ext: ext_amount = qty * unit_price (NULL qty -> NULL ext_amount) ---
    def compute_ext(row):
        qty = row["qty"]
        unit_price = row["unit_price"]
        if pd.isna(qty):
            return np.nan
        return qty * unit_price

    orders["ext_amount"] = orders.apply(compute_ext, axis=1)

    # --- router: first matching rule wins, NULL predicate not true ---
    def route_fn(row):
        price_flag = row["price_flag"]
        qty = row["qty"]
        ext_amount = row["ext_amount"]

        # REVIEW: price_flag == 'NO_PRICE' or qty is NULL or qty >= 100
        cond_review = False
        if price_flag == "NO_PRICE":
            cond_review = True
        elif pd.isna(qty):
            cond_review = True
        else:
            if qty >= 100:
                cond_review = True

        if cond_review:
            return "REVIEW"

        # BULK: ext_amount >= 1000 (NULL predicate -> not true)
        if not pd.isna(ext_amount) and ext_amount >= 1000:
            return "BULK"

        # SMALL: ext_amount < 50 (NULL predicate -> not true)
        if not pd.isna(ext_amount) and ext_amount < 50:
            return "SMALL"

        return "STANDARD"

    orders["route"] = orders.apply(route_fn, axis=1)

    # --- out1: order_enriched ---
    order_enriched = orders[["order_id", "sku_norm", "unit_price", "route"]].copy()

    # --- agg: group by route, order_date ---
    grouped = orders.groupby(["route", "order_date"], dropna=False).agg(
        order_count=("order_id", "count"),
        total_ext=("ext_amount", "sum"),
    ).reset_index()

    # Ensure sum of all-NaN group is 0 (pandas default sum behavior already gives 0.0)
    grouped["total_ext"] = grouped["total_ext"].fillna(0.0)

    route_daily = grouped[["route", "order_date", "order_count", "total_ext"]].copy()

    return {
        "order_enriched": order_enriched,
        "route_daily": route_daily,
    }
